const music = new Audio('./assets/audio/sea.mp3'); music.loop = true; music.volume = .23; music.preload = 'none';
const cue = new Audio(); cue.volume = .42; cue.preload = 'none';
function toast(text) { $('#toast').textContent = text; $('#toast').classList.add('show'); clearTimeout(toastTimer); toastTimer = setTimeout(() => $('#toast').classList.remove('show'), 3500); }
async function setAudio(value) { state.audio = value; $('#music').setAttribute('aria-pressed', String(value)); $('#music').setAttribute('aria-label', value ? 'Mute music' : 'Enable music'); if (value) { try { await music.play(); } catch { state.audio=false; $('#music').setAttribute('aria-pressed','false'); $('#music').setAttribute('aria-label','Enable music'); toast('Tap the sound control to start music.'); } } else { music.pause(); cue.pause(); } }
function playCue(id) { cue.pause(); if (!state.audio || !id) return; cue.src = `./assets/audio/${id}.mp3`; music.volume = .09; cue.play().catch(() => { music.volume = .23; }); }
cue.addEventListener('ended', () => { music.volume = .23; });
$('#music').addEventListener('click', () => setAudio(!state.audio));
document.addEventListener('visibilitychange', () => { if (document.hidden) { music.pause(); cue.pause(); } else if (state.audio) music.play().catch(() => {}); });
function dialog(content) { $('#content-body').innerHTML = content; if (!$('#content-dialog').open) $('#content-dialog').showModal(); }
$$('dialog').forEach(d => { d.querySelector('[data-close]').addEventListener('click', () => d.close()); d.addEventListener('click', e => { if (e.target === d) { const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close(); } }); });
$('#menu').addEventListener('click', () => $('#nav-dialog').showModal());
function captain() { dialog(`<span class="micro">THE CAPTAIN'S LOG</span><h2 class="dialog-title" id="content-title">RAGHAVENDRA PEDADA</h2><div class="captain-grid"><img src="./assets/raghavendra-portrait.jpg" alt="Raghavendra Pedada"><div><p>I'm a Full-Stack Developer and Computer Science undergraduate at Alva's Institute of Engineering & Technology, Class of 2027. I build AI-powered applications, blockchain systems and IoT solutions.</p><h3>Software Testing Intern · IFB Automotive</h3><p>September 2026 — Present. Testing Industrial Internet of Things software and developing IFBConnect, a local-network chat application for internal communication.</p><h3>B.E. Computer Science Engineering · 2023–2027</h3><p>Specialising in IoT, Cyber Security and Blockchain, with a foundation in data structures, databases, operating systems and computer networks.</p></div></div><div class="tags"><span>Python</span><span>React</span><span>FastAPI</span><span>Solidity</span><span>IoT</span></div><div class="dialog-bottom"><a class="solid-button" href="./assets/Raghavendra-Pedada-Resume.pdf" download="Raghavendra-Pedada-Resume.pdf">DOWNLOAD RÉSUMÉ ↓</a><a class="lite-link" href="./lite.html#about">READ THE FULL PORTFOLIO ↗</a></div>`); }
function projectDetail() { const p=projects[state.project]; dialog(`<span class="micro">EXPEDITION 0${state.project+1} / ${p.category}</span><h2 class="dialog-title" id="content-title">${p.display}</h2><p class="dialog-lead">${p.detail}</p><div class="tags">${p.tags.map(t=>`<span>${t}</span>`).join('')}</div><div class="dialog-columns"><div><h3>${p.focus}</h3><p>${p.description}</p></div><div><h3>Conceptual flow</h3><p>${p.flow}</p><p>Explore the repository for the implementation and documentation.</p></div></div><div class="dialog-bottom"><a class="solid-button" href="${p.url}" target="_blank" rel="noopener noreferrer">EXPLORE THE SOURCE ↗</a><button id="next-log">NEXT EXPEDITION →</button></div>`); $('#next-log').addEventListener('click',()=>{selectProject((state.project+1)%3);projectDetail();$('#content-dialog').scrollTop=0;}); }
function crewDetail() { const c=crew[state.crew]; dialog(`<span class="micro">CREW INSPIRATION / ${c.role}</span><h2 class="dialog-title" id="content-title">${c.quality}</h2><p class="dialog-lead">${c.description}</p><div class="dialog-columns"><div><h3>My toolkit: ${c.skill}</h3><div class="tags">${c.tags.map(t=>`<span>${t}</span>`).join('')}</div></div><div><h3>Inspired by ${c.name}</h3><p>The Straw Hats give this portfolio its spirit. The technologies listed here are drawn from my own projects and experience.</p></div></div><div class="dialog-bottom"><a class="solid-button" href="./lite.html#crew">ALL SKILLS ↗</a><button id="next-crew-detail">NEXT CREWMATE →</button></div>`);$('#next-crew-detail').addEventListener('click',()=>{selectCrew((state.crew+1)%crew.length);crewDetail();}); }
function contact() { dialog(`<span class="micro">PURU PURU PURU…</span><h2 class="dialog-title" id="content-title">A LINE IS<br>ALWAYS OPEN.</h2><p class="dialog-lead">Open to collaborations, projects and interesting conversations. AI, blockchain, IoT or full-stack—let's talk.</p><div class="contact-links"><a href="mailto:raghavendrapedadaa@gmail.com">EMAIL ↗</a><a href="https://github.com/RaghavendraPedada-1765" target="_blank" rel="noopener noreferrer">GITHUB ↗</a><a href="https://www.linkedin.com/in/raghavendra-pedada-baa349356/" target="_blank" rel="noopener noreferrer">LINKEDIN ↗</a></div><div class="dialog-bottom"><a class="solid-button" href="mailto:raghavendrapedadaa@gmail.com">LET'S BUILD SOMETHING ↗</a><button id="copy-email">COPY EMAIL ⧉</button></div>`);$('#copy-email').addEventListener('click',async()=>{try{await navigator.clipboard.writeText('raghavendrapedadaa@gmail.com');toast('Email address copied.');}catch{toast('raghavendrapedadaa@gmail.com');}}); }
$('#scene-action').addEventListener('click', () => { [captain,crewDetail,projectDetail,captain,contact][state.scene](); });
function refreshCopy() {
 const s=scenes[state.scene];$('#scene-label').textContent=s.label;$('#scene-title').innerHTML=s.title;$('#scene-description').textContent=s.description;$('#scene-action').innerHTML=`${s.action} <span aria-hidden="true">↗</span>`;
 if(state.scene===1){const c=crew[state.crew];$('#scene-label').textContent=`01 / ${c.role}`;$('#scene-title').innerHTML=c.name.split(' ').length>2?`${c.name.split(' ').slice(0,-1).join(' ')}<br><span>${c.name.split(' ').at(-1)}.</span>`:`<span>${c.name}.</span>`;$('#scene-description').textContent=`${c.quality} ${c.description}`;}
 if(state.scene===2){const p=projects[state.project];$('#scene-label').textContent=`02 / ${p.category}`;$('#scene-title').innerHTML=`<span>${p.name}.</span>`;$('#scene-description').textContent=p.description;}
 $('#scene-count').textContent=String(state.scene+1).padStart(2,'0');$('#chapter-marker').textContent=`THE GRAND LINE / ${String(state.scene+1).padStart(3,'0')}`;
 document.body.classList.toggle('crew-mode',state.scene===1);$$('.scene-tabs button').forEach(b=>{b.classList.toggle('active',Number(b.dataset.scene)===state.scene);b.setAttribute('aria-current',Number(b.dataset.scene)===state.scene?'page':'false');});
}
function updateSubnav() { const list=state.scene===1?crew.map(c=>c.name):state.scene===2?projects.map(p=>p.display):[];$('#scene-subnav').innerHTML=list.map((n,i)=>`<button data-object="${i}" class="${i===(state.scene===1?state.crew:state.project)?'active':''}"><span>${String(i+1).padStart(2,'0')}</span>${n}</button>`).join('');$$('[data-object]').forEach(b=>b.addEventListener('click',()=>state.scene===1?selectCrew(Number(b.dataset.object)):selectProject(Number(b.dataset.object)))); }
async function selectCrew(index) { state.crew=index;refreshCopy();updateSubnav();playCue(crew[index].audio);await world?.showCrew(crew[index].id); }
function selectProject(index) { state.project=index;refreshCopy();updateSubnav();world?.showProject(index); }
function go(index) { if(!state.entered||state.flying)return;state.scene=(index+scenes.length)%scenes.length;$('#nav-dialog').close();$('#scene-copy').classList.add('changing');clearTimeout(sceneTimer);world?.go(state.scene);sceneTimer=setTimeout(()=>{$('#scene-copy').classList.remove('changing');refreshCopy();updateSubnav();},state.reduced?0:220);if(state.scene===1)selectCrew(state.crew); }
$$('[data-scene]').forEach(b=>b.addEventListener('click',()=>go(Number(b.dataset.scene))));$('#previous').addEventListener('click',()=>go(state.scene-1));$('#next').addEventListener('click',()=>go(state.scene+1));
addEventListener('wheel',event=>{if(!state.entered||state.flying||$('dialog[open]')||event.target.closest('.scene-subnav')||Math.abs(event.deltaY)<15)return;const now=performance.now();if(now-wheelTime>1100){wheelTime=now;go(state.scene+Math.sign(event.deltaY));}},{passive:true});
addEventListener('keydown',event=>{if(!state.entered||state.flying||$('dialog[open]')||event.target.closest('button,a,input'))return;if(event.key==='ArrowRight'||event.key==='ArrowDown'){event.preventDefault();go(state.scene+1);}if(event.key==='ArrowLeft'||event.key==='ArrowUp'){event.preventDefault();go(state.scene-1);}});
$('#reduce-motion').checked=state.reduced;$('#reduce-motion').addEventListener('change',e=>{state.reduced=e.target.checked;world?.setReduced(state.reduced);if(state.reduced&&state.flying)finishIntro();});reducedPreference.addEventListener('change',e=>{state.reduced=e.matches;$('#reduce-motion').checked=e.matches;world?.setReduced(e.matches);});
$('#quality').addEventListener('click',()=>{state.low=!state.low;world?.setLow(state.low);$('#quality').setAttribute('aria-pressed',String(state.low));$('#quality').textContent=state.low?'FULL EFFECTS':'LIGHTER EFFECTS';toast(state.low?'Lighter effects enabled.':'Full effects enabled.');});
function finishIntro(){if(!state.flying)return;state.flying=false;document.body.classList.remove('flying');$('#hud').inert=false;world?.finishIntro();refreshCopy();}
$('#skip-intro').addEventListener('click',finishIntro);
async function enter(replay=false){if(busy||!world)return;busy=true;state.entered=true;state.scene=0;$('#launch').classList.add('exit');$('#launch').inert=true;document.body.classList.add('entered');if(!replay&&$('#start-audio').checked)await setAudio(true);if(state.reduced){$('#hud').inert=false;world.finishIntro();}else{state.flying=true;document.body.classList.add('flying');$('#hud').inert=true;world.startIntro();}refreshCopy();updateSubnav();busy=false;}
$('#enter').addEventListener('click',()=>enter());$('#replay').addEventListener('click',()=>{$('#nav-dialog').close();enter(true);});
function progress(percent,label){const n=Math.round(Math.max(0,Math.min(100,percent)));$('#load-percent').textContent=n;$('#load-fill').style.width=n+'%';$('.load-track').setAttribute('aria-valuenow',n);$('#load-detail').textContent=label;}
function fail(error){console.warn('Experience unavailable',error);document.body.classList.add('fallback');$('#load-label').textContent='LITE MODE AVAILABLE';$('#load-detail').textContent='The 3D scene could not load. Open the Lite portfolio below.';toast('Your full portfolio is available in Lite mode.');}
try{world=new GrandLine($('#ocean-world'),{reduced:state.reduced,onProgress:progress,onIntroEnd:finishIntro,onIntroCaption:text=>{$('#intro-line').textContent=text;},onLoading:text=>{$('#object-loading').textContent=text;$('#object-loading').classList.toggle('visible',!!text);},onObject:()=>{if(state.scene===1)crewDetail();else if(state.scene===2)projectDetail();else if(state.scene===3)captain();else if(state.scene===4)contact();},onError:message=>toast(message)});await world.load();progress(100,'Sunny ready. The Grand Line is yours.');$('#load-label').textContent='READY TO SET SAIL';$('#enter').disabled=false;$('#enter').innerHTML='ENTER THE GRAND LINE <span aria-hidden="true">↗</span>';}catch(error){fail(error);}
